                        atomicAdd(vk+(j0+0)*nao+(k0+1), gout[4]*dm[(i0+6)*nao+(l0+0)] + gout[15]*dm[(i0+4)*nao+(l0+1)] + gout[26]*dm[(i0+2)*nao+(l0+2)]);
