                        atomicAdd(vk+(j0+0)*nao+(k0+2), gout[7]*dm[(i0+1)*nao+(l0+0)] + gout[8]*dm[(i0+9)*nao+(l0+0)] + gout[19]*dm[(i0+7)*nao+(l0+1)] + gout[30]*dm[(i0+5)*nao+(l0+2)]);
                        atomicAdd(vk+(j0+1)*nao+(k0+2), gout[9]*dm[(i0+7)*nao+(l0+0)] + gout[20]*dm[(i0+5)*nao+(l0+1)] + gout[31]*dm[(i0+3)*nao+(l0+2)]);
                        atomicAdd(vk+(j0+2)*nao+(k0+2), gout[10]*dm[(i0+5)*nao+(l0+0)] + gout[21]*dm[(i0+3)*nao+(l0+1)] + gout[32]*dm[(i0+1)*nao+(l0+2)] + gout[33]*dm[(i0+9)*nao+(l0+2)]);
