// (fs|fs): 100 outputs, 4 threads x 64 quartets per block, 25 outputs per thread, g_size 16
__global__ static
void rys_k_gen_3030(JKMATRIX_KERNEL_ARGS)
{
    JKMATRIX_KERNEL_SETUP();

    int t_id = 64 * gout_id + sq_id;
