                        atomicAdd(vk+(j0+5)*nao+(l0+0), gout[12]*dm[(i0+0)*nao+(k0+0)] + gout[13]*dm[(i0+4)*nao+(k0+0)] + gout[14]*dm[(i0+8)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(l0+0), gout[15]*dm[(i0+2)*nao+(k0+0)] + gout[16]*dm[(i0+6)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(l0+0), gout[17]*dm[(i0+0)*nao+(k0+0)] + gout[18]*dm[(i0+4)*nao+(k0+0)] + gout[19]*dm[(i0+8)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(l0+0), gout[20]*dm[(i0+2)*nao+(k0+0)] + gout[21]*dm[(i0+6)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(l0+0), gout[22]*dm[(i0+0)*nao+(k0+0)] + gout[23]*dm[(i0+4)*nao+(k0+0)] + gout[24]*dm[(i0+8)*nao+(k0+0)]);
                        break; }
                    case 3: {
                        atomicAdd(vk+(j0+0)*nao+(l0+0), gout[0]*dm[(i0+3)*nao+(k0+0)] + gout[1]*dm[(i0+7)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+1)*nao+(l0+0), gout[2]*dm[(i0+1)*nao+(k0+0)] + gout[3]*dm[(i0+5)*nao+(k0+0)] + gout[4]*dm[(i0+9)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+2)*nao+(l0+0), gout[5]*dm[(i0+3)*nao+(k0+0)] + gout[6]*dm[(i0+7)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+3)*nao+(l0+0), gout[7]*dm[(i0+1)*nao+(k0+0)] + gout[8]*dm[(i0+5)*nao+(k0+0)] + gout[9]*dm[(i0+9)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+4)*nao+(l0+0), gout[10]*dm[(i0+3)*nao+(k0+0)] + gout[11]*dm[(i0+7)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+5)*nao+(l0+0), gout[12]*dm[(i0+1)*nao+(k0+0)] + gout[13]*dm[(i0+5)*nao+(k0+0)] + gout[14]*dm[(i0+9)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(l0+0), gout[15]*dm[(i0+3)*nao+(k0+0)] + gout[16]*dm[(i0+7)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(l0+0), gout[17]*dm[(i0+1)*nao+(k0+0)] + gout[18]*dm[(i0+5)*nao+(k0+0)] + gout[19]*dm[(i0+9)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(l0+0), gout[20]*dm[(i0+3)*nao+(k0+0)] + gout[21]*dm[(i0+7)*nao+(k0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(l0+0), gout[22]*dm[(i0+1)*nao+(k0+0)] + gout[23]*dm[(i0+5)*nao+(k0+0)] + gout[24]*dm[(i0+9)*nao+(k0+0)]);
                        break; }
                    }
                    switch (gout_id) {
                    case 0: {
                        atomicAdd(vk+(j0+0)*nao+(k0+0), gout[0]*dm[(i0+0)*nao+(l0+0)] + gout[1]*dm[(i0+4)*nao+(l0+0)] + gout[2]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+1)*nao+(k0+0), gout[3]*dm[(i0+2)*nao+(l0+0)] + gout[4]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+2)*nao+(k0+0), gout[5]*dm[(i0+0)*nao+(l0+0)] + gout[6]*dm[(i0+4)*nao+(l0+0)] + gout[7]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+3)*nao+(k0+0), gout[8]*dm[(i0+2)*nao+(l0+0)] + gout[9]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+4)*nao+(k0+0), gout[10]*dm[(i0+0)*nao+(l0+0)] + gout[11]*dm[(i0+4)*nao+(l0+0)] + gout[12]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+5)*nao+(k0+0), gout[13]*dm[(i0+2)*nao+(l0+0)] + gout[14]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(k0+0), gout[15]*dm[(i0+0)*nao+(l0+0)] + gout[16]*dm[(i0+4)*nao+(l0+0)] + gout[17]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(k0+0), gout[18]*dm[(i0+2)*nao+(l0+0)] + gout[19]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(k0+0), gout[20]*dm[(i0+0)*nao+(l0+0)] + gout[21]*dm[(i0+4)*nao+(l0+0)] + gout[22]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(k0+0), gout[23]*dm[(i0+2)*nao+(l0+0)] + gout[24]*dm[(i0+6)*nao+(l0+0)]);
                        break; }
                    case 1: {
                        atomicAdd(vk+(j0+0)*nao+(k0+0), gout[0]*dm[(i0+1)*nao+(l0+0)] + gout[1]*dm[(i0+5)*nao+(l0+0)] + gout[2]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+1)*nao+(k0+0), gout[3]*dm[(i0+3)*nao+(l0+0)] + gout[4]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+2)*nao+(k0+0), gout[5]*dm[(i0+1)*nao+(l0+0)] + gout[6]*dm[(i0+5)*nao+(l0+0)] + gout[7]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+3)*nao+(k0+0), gout[8]*dm[(i0+3)*nao+(l0+0)] + gout[9]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+4)*nao+(k0+0), gout[10]*dm[(i0+1)*nao+(l0+0)] + gout[11]*dm[(i0+5)*nao+(l0+0)] + gout[12]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+5)*nao+(k0+0), gout[13]*dm[(i0+3)*nao+(l0+0)] + gout[14]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(k0+0), gout[15]*dm[(i0+1)*nao+(l0+0)] + gout[16]*dm[(i0+5)*nao+(l0+0)] + gout[17]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(k0+0), gout[18]*dm[(i0+3)*nao+(l0+0)] + gout[19]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(k0+0), gout[20]*dm[(i0+1)*nao+(l0+0)] + gout[21]*dm[(i0+5)*nao+(l0+0)] + gout[22]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(k0+0), gout[23]*dm[(i0+3)*nao+(l0+0)] + gout[24]*dm[(i0+7)*nao+(l0+0)]);
                        break; }
                    case 2: {
                        atomicAdd(vk+(j0+0)*nao+(k0+0), gout[0]*dm[(i0+2)*nao+(l0+0)] + gout[1]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+1)*nao+(k0+0), gout[2]*dm[(i0+0)*nao+(l0+0)] + gout[3]*dm[(i0+4)*nao+(l0+0)] + gout[4]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+2)*nao+(k0+0), gout[5]*dm[(i0+2)*nao+(l0+0)] + gout[6]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+3)*nao+(k0+0), gout[7]*dm[(i0+0)*nao+(l0+0)] + gout[8]*dm[(i0+4)*nao+(l0+0)] + gout[9]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+4)*nao+(k0+0), gout[10]*dm[(i0+2)*nao+(l0+0)] + gout[11]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+5)*nao+(k0+0), gout[12]*dm[(i0+0)*nao+(l0+0)] + gout[13]*dm[(i0+4)*nao+(l0+0)] + gout[14]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(k0+0), gout[15]*dm[(i0+2)*nao+(l0+0)] + gout[16]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(k0+0), gout[17]*dm[(i0+0)*nao+(l0+0)] + gout[18]*dm[(i0+4)*nao+(l0+0)] + gout[19]*dm[(i0+8)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(k0+0), gout[20]*dm[(i0+2)*nao+(l0+0)] + gout[21]*dm[(i0+6)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(k0+0), gout[22]*dm[(i0+0)*nao+(l0+0)] + gout[23]*dm[(i0+4)*nao+(l0+0)] + gout[24]*dm[(i0+8)*nao+(l0+0)]);
                        break; }
                    case 3: {
                        atomicAdd(vk+(j0+0)*nao+(k0+0), gout[0]*dm[(i0+3)*nao+(l0+0)] + gout[1]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+1)*nao+(k0+0), gout[2]*dm[(i0+1)*nao+(l0+0)] + gout[3]*dm[(i0+5)*nao+(l0+0)] + gout[4]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+2)*nao+(k0+0), gout[5]*dm[(i0+3)*nao+(l0+0)] + gout[6]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+3)*nao+(k0+0), gout[7]*dm[(i0+1)*nao+(l0+0)] + gout[8]*dm[(i0+5)*nao+(l0+0)] + gout[9]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+4)*nao+(k0+0), gout[10]*dm[(i0+3)*nao+(l0+0)] + gout[11]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+5)*nao+(k0+0), gout[12]*dm[(i0+1)*nao+(l0+0)] + gout[13]*dm[(i0+5)*nao+(l0+0)] + gout[14]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+6)*nao+(k0+0), gout[15]*dm[(i0+3)*nao+(l0+0)] + gout[16]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+7)*nao+(k0+0), gout[17]*dm[(i0+1)*nao+(l0+0)] + gout[18]*dm[(i0+5)*nao+(l0+0)] + gout[19]*dm[(i0+9)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+8)*nao+(k0+0), gout[20]*dm[(i0+3)*nao+(l0+0)] + gout[21]*dm[(i0+7)*nao+(l0+0)]);
                        atomicAdd(vk+(j0+9)*nao+(k0+0), gout[22]*dm[(i0+1)*nao+(l0+0)] + gout[23]*dm[(i0+5)*nao+(l0+0)] + gout[24]*dm[(i0+9)*nao+(l0+0)]);
                        break; }
                    }
                }
            }
        }
    }
}
}

// (ds|dd): 216 outputs, 8 threads x 32 quartets per block, 27 outputs per thread, g_size 27
__global__ static
void rys_k_gen_2022(JKMATRIX_KERNEL_ARGS)
{
    JKMATRIX_KERNEL_SETUP();

    int t_id = 32 * gout_id + sq_id;
    constexpr int threads = 256;
    constexpr int nsq_per_block = 32;
    constexpr int g_size = 27;
    uint32_t nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;

    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * (g_size*3+6) + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (g_size*3+bounds.nroots*2+6);
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_vk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                       q_cond_ij, q_cond_kl, dm_penalty,
                       (int *)shared_memory, envs, bounds);
    } else {
        _fill_sr_vk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                          q_cond_ij, q_cond_kl, dm_penalty,
                          s_cond_ij, s_cond_kl, diffuse_exps,
                          (int *)shared_memory, jk.omega, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        __syncthreads();
        int iprim = bounds.iprim;
        int jprim = bounds.jprim;
        int kprim = bounds.kprim;
        int lprim = bounds.lprim;
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            double xlxk = env[rl+0] - env[rk+0];
            double ylyk = env[rl+1] - env[rk+1];
            double zlzk = env[rl+2] - env[rk+2];
            rlrk[0*nsq_per_block] = xlxk;
            rlrk[1*nsq_per_block] = ylyk;
            rlrk[2*nsq_per_block] = zlzk;
        }
        double gout[27];
#pragma unroll
        for (int n = 0; n < 27; ++n) { gout[n] = 0; }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            int kp = klp / lprim;
            int lp = klp % lprim;
            int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
            int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double akl = ak + al;
            double al_akl = al / akl;
            if (gout_id == 0) {
                int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
                int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
                double xlxk = rlrk[0*nsq_per_block];
                double ylyk = rlrk[1*nsq_per_block];
                double zlzk = rlrk[2*nsq_per_block];
                double theta_kl = ak * al_akl;
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                double fac_sym = PI_FAC;
                if (task_id < ntasks) {
                    if (ksh == lsh) fac_sym *= .5;
                    if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
                } else {
                    fac_sym = 0;
                }
                gx[0] = fac_sym * ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                __syncthreads();
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + rlrk[0*nsq_per_block] * al_akl;
                double ykl = env[rk+1] + rlrk[1*nsq_per_block] * al_akl;
                double zkl = env[rk+2] + rlrk[2*nsq_per_block] * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                int nroots = bounds.nroots;
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 8, gout_id);
                if (gout_id == 0) {
                    Rpq[0*nsq_per_block] = xpq;
                    Rpq[1*nsq_per_block] = ypq;
                    Rpq[2*nsq_per_block] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[nsq_per_block*g_size] = cicj / (aij*akl*sqrt(aij+akl));
                }
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*64];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double b10 = .5/aij * (1 - rt_aij);
                    double rt_akl = rt_aa * aij;
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 8) {
                        if (n == 2) {
                            gx[1728] = rw[irys*64+32];
                        }
                        double *_gx = gx + n * 864;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[32] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[64] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[96] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[192] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[288] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        _gx[384] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[128] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[96];
                        _gx[224] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[192];
                        _gx[320] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 1 * b00 * _gx[288];
                        _gx[416] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[160] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[128];
                        _gx[256] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[224];
                        _gx[352] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 2 * b00 * _gx[320];
                        _gx[448] = s2;
                        s1 = _gx[384];
                        s0 = _gx[288];
                        _gx[576] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[480] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[96];
                        _gx[384] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[0];
